\label{Theorem: main theorem for sl2 ADO}

If $L$ is a Murasugi sum of $L_1$ and $L_2$ along minimal genus connected Seifert surfaces, then $$\mathrm{top}^{ADO}_p(L)=\mathrm{top}^{ADO}_p(L_1)\cdot\mathrm{top}^{ADO}_p(L_2)$$
for any $p\geq 2$.

\label{corollary: fibred}
    For every simple $\mathfrak{g}$ of type ADE and integer $r\geq 3$, the top coefficient of $\text{ADO}_{\mathfrak{g},r}(L)$ of a fibred link $L$ is a power of $q$, namely $$\text{top}_{\mathfrak{g},r}(L)=q^{-(2\rho,2\rho)(n_--m_-)}$$
    where $n_-, m_-$ are as above and $2\rho=\sum_{\beta\in\Delta^+}\beta$.

\label{theorem: top coefficient formula with integral}
Suppose $(r,\det(A))=1$. Let $\Sigma$ be a connected minimal genus Seifert surface of a link $L$ and let $T_{\Sigma}$ be a (framed) bottom tangle such that $\Sigma$ is obtained by gluing a single disk to the top of $T_{\Sigma}$. Let $Z_{T_{\Sigma}}\in \mathfrak{u}_q(\mathfrak{g})^{\otimes N}$ be the universal $\mathfrak{u}_q(\mathfrak{g})$-invariant of $T_{\Sigma}$ ($N=2g(L)+s-1$ as before). Then
    $$\text{top}_{\mathfrak{g},r}(L)=\frac{ \overline{\mu}^{\otimes N}(Z_{T_{\Sigma}})}{q^{(2\rho,2\rho)N}\cdot\overline{\mu}(v)^N} 

    $$
    where $v$ is the ribbon element of $\mathfrak{u}_q(\mathfrak{g})$\footnote{In the present paper, the convention is that a positive twist acts by the ribbon element $v\in \mathfrak{u}_q(\mathfrak{g})$.} (for an explicit expression of $\overline{\mu}(v)$ see Remark \ref{remark: scalar ovmu on ribbon v}).

\cite{CP:BOOK}
\label{lemma: PBW belongs to V+}
For each positive root $\beta$, $E_{\beta}\in U^+$ and $\{E^I \ | \ I:\Delta^+\to \mathbb{N}_{\geq 0}\}$ is a basis of $U^+$. Similarly $F_{\beta}\in U^-$ and $\{F^I \ | \ I:\Delta^+\to \mathbb{N}_{\geq 0}\}$ is a basis of $U^-.$

\label{lemma: coev lemma}
    We have $(\iota_X\otimes (\overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}\circ\overrightarrow{\text{ev}}_{V_{\boldsymbol{\lambda}}}))\circ\overrightarrow{\text{coev}}_X=\overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}\otimes\overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}$
    or graphically
    \begin{figure}[H]
        \centering
        \includegraphics[width=6cm]{Lemma_4.6_on_pivotal_structure.pdf}
    \end{figure}
    where the thick strand is colored by $X$ and all other strands are colored with $V_{\boldsymbol{\lambda}}$.

By the formula for the braiding in $\mathcal{C}^H_{[0]}\subset \mathcal{C}^H_{\mathfrak{g},r}$, the lemma amounts to prove that the diagonal operator $\mathcal{H}$ can be written as left multiplication by $\overline{\mathcal{K}}\in \mathbb{Q}(q)[L]^{\otimes 2}$. We prove it for $L=L_W$ (which works for all $\mathfrak{g}$ and $r$). Then, we want to show that there are coefficients $c_{\alpha,\beta}\in\mathbb{Q}(q)$ such that $$q^{(\lambda,\mu)}=\sum_{\alpha,\beta\in L_W}c_{\alpha,\beta}\cdot q^{(\alpha,\lambda)+(\beta,\mu)}$$
for all $\lambda,\mu\in L_R$. Writing $\lambda=\sum a_i\alpha_i, \mu=\sum b_i\alpha_i$ and $\alpha=\sum u_i\widehat{H}_i, \beta=\sum v_i\widehat{H}_i$ ($a_i,b_i,u_i,v_i\in \mathbb{Z}$) where $(\widehat{H}_i)\subset L_W$ is the dual basis of $(H_i)$, the above equation becomes 
\begin{align}
    \label{eq: qbAc as a sum}
    q^{\sum a_{ij}a_ib_j}=\sum_{\boldsymbol{u},\boldsymbol{v}\in L_W} c_{\boldsymbol{u},\boldsymbol{v}}\cdot q^{\sum u_ia_i+v_ib_i}.
\end{align}
For this, it suffices to prove that, given a fixed $a\in \mathbb{Z}$ there are coefficients $c_{i,j}\in \mathbb{Q}(q)$ such that 
\begin{align}
    \label{eq: writing qabc as a sum}
    q^{a(bc)}=\sum_{i,j}c_{ij}\cdot q^{bi+cj}
\end{align}
for all $b,c\in\mathbb{Z}$. For $a=0$ this is obvious (set $c_{00}=1$ and $c_{ij}=0$ otherwise).
When $(r,a)=1$ it suffices to set $c_{ij}=q^{-a'ij}$ where $a'$ is the inverse mod $r$ of $a$, and sum over $i,j\in \{0,\dots,r-1\}$. If $(r,a)=d>1$ then $\omega=q^a$ is a root of 1 of order $r/d$ so what we just showed proves that $\omega^{bc}=\sum c'_{i',j'}\omega^{bi'+cj'}$ for some $c'_{i',j'}\in\mathbb{Q}(q)$. Setting $c_{i,j}=0$ if either $i,j$ are not divisible by $a$ and $c_{ai',aj'}=c'_{i',j'}$ proves (\ref{eq: writing qabc as a sum}). Applying (\ref{eq: writing qabc as a sum}) $n^2$ times to $q^{\sum a_{ij}a_ib_j}=\prod_{i,j}q^{a_{ij}a_ib_j}$ gives an expression of the form (\ref{eq: qbAc as a sum}).


\medskip
    The statement for $(r,\det(A))=1$ is proven in \cite[Lemma 2.4]{LNV:genus-unrolled}. The statement for $\mathfrak{sl}_2$ is well-known and proved similarly.

\label{prop: symmetry of ADO}
The scalars $\text{ADO}_{\mathfrak{g},r}(L,\boldsymbol{\lambda})$ satisfy $$\text{ADO}_{\mathfrak{g},r}(L,\boldsymbol{\lambda})=\text{ADO}_{\mathfrak{g},r}(L,-\boldsymbol{\lambda}+(r'-1)2\rho).$$
In particular, if $\mathfrak{g}$ is simply-laced then $\text{ADO}_{\mathfrak{g},r}(L)$ is invariant under the transformation of variables $t_i^{\frac{1}{2}}\mapsto t_i^{-\frac{1}{2}}q^{-2}$ for all $i=1,\dots,n$.

\cite{LNV:genus-unrolled}
\label{lemma: Ei coefficients action on Va}
    In the standard basis of $V_{\lambda}$, $E_i$ acts by a matrix with coefficients of the form $a(q)t^{\frac{1}{2}}+b(q)t^{-\frac{1}{2}}$ with $a(q),b(q)\in \mathbb{Q}(q)$.  In the dual basis of $V_{\lambda}^*$, $E_i$ acts by a matrix with coefficients of the form $c(q)+d(q)t^{-1}$, $c(q),d(q)\in \mathbb{Q}(q)$.

\cite{LNV:genus-unrolled}
\label{lemma: algebraic bounds}
    A PBW basis vector $K^AF^IE^J$  acts on the standard basis of $X$ by a matrix whose coefficients are (plain, non-Laurent) polynomials in $t^{-1}$ of degree $\leq |J|$. In particular, all coefficients have degree $\leq (r'-1)(2\rho,\rho)$ in $t^{-1}$.

\label{lemma: CGPT's lemma for cointegral}
For any typical $\boldsymbol{\lambda}$, there is a constant $\kappa_{\Lambda}(\boldsymbol{\lambda})\in \mathbb{Q}(q,q^{\pm \lambda_1},\dots,q^{\pm\lambda_n})$ such that $$\Lambda|_{V_{\boldsymbol{\lambda}}\otimesV_{\boldsymbol{\lambda}}^*}=\kappa_{\Lambda}(\lambda)\cdot  \overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}\circ \overrightarrow{\text{ev}}_{V_{\boldsymbol{\lambda}}}.$$
Moreover, if $\Lambda=\frac{1}{|G|}\sum_{g\in G}g\cdot F^{I_{max}}E^{I_{max}}$, the scalar $\kappa_{\Lambda}(\lambda)$ coincides with the coefficient of the highest weight vector $v_0$ in $E^{I_{max}}F^{I_{max}}v_0$.

The first part is essentially a special case of \cite[Lemma 6.2]{CGPT} as we now explain. For every projective $\mathfrak{u}_q^{L}(\mathfrak{g})$-module $P$, it is shown in \cite[Lemma 6.2]{CGPT} that there is a non-degenerate pairing\footnote{The above non-degenerate pairing is the so called ``modified trace'' of Geer, Patureau-Mirand and Turaev \cite{GPT:modified}, but we won't need this.} $$\text{Hom}\,_{\mathfrak{u}_q^{L}(\mathfrak{g})}(\mathbbm{1},P)\otimes \text{Hom}\,_{\mathfrak{u}_q^{L}(\mathfrak{g})}(P,\mathbbm{1})\to \mathbb{C}$$
such that if $(x_i)$ is a basis of $\text{Hom}\,_{\mathfrak{u}_q^{L}(\mathfrak{g})}(\mathbbm{1},P)$ and $(y_i)$ is the dual basis of $\text{Hom}\,_{\mathfrak{u}_q^{L}(\mathfrak{g})}(P,\mathbbm{1})$ under this pairing, then the cointegral $\Lambda$ acts on $P$ as 
\begin{equation}
\label{eq: cointegral on projective}
    \Lambda|_P=\gamma\sum_i x_i\circ y_i
\end{equation}
where $\gamma$ is some scalar (which can be chosen to be 1 if appropriate normalizations for the pairing and $\Lambda$ are chosen). Now if we let $P=V_{\boldsymbol{\lambda}}\otimes V_{\boldsymbol{\lambda}}^*$ (which is projective since $V_{\boldsymbol{\lambda}}$ is), then both $\text{Hom}\,_{\mathcal{C}^H_{\mathfrak{g},r}}(\mathbbm{1},P), \text{Hom}\,_{\mathcal{C}^H_{\mathfrak{g},r}}(P,\mathbbm{1})$ are 1-dimensional (since both are isomorphic to $\text{End}_{\mathcal{C}^H_{\mathfrak{g},r}}(V_{\boldsymbol{\lambda}})$ and $V_{\boldsymbol{\lambda}}$ is simple), hence $\overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}$ and $\overrightarrow{\text{ev}}_{V_{\boldsymbol{\lambda}}}$ (which are non-zero) are bases of each space. It follows that $\overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}$ and $\overrightarrow{\text{ev}}_{V_{\boldsymbol{\lambda}}}$ are dual bases up to a scalar, so that the lemma follows by plugging these bases in (\ref{eq: cointegral on projective}).
\medskip

Now fix $\Lambda=\frac{1}{|G|}\sum_{g\in G}g\cdot F^{I_{max}}E^{I_{max}}$. The scalar $\kappa_{\Lambda}(\lambda)$ is computed explicitly by taking left-traces on both sides of the above equation: this gives
 $$\text{tr}\,_{V_{\boldsymbol{\lambda}}}(K_{2\rho}^{r'-1}\Lambda_{(1)})\Lambda_{(2)}|_{V_{\boldsymbol{\lambda}}^*}=\kappa(\lambda)\text{id}_{V_{\boldsymbol{\lambda}}^*}$$
Applying this to the highest weight vector $v'_{min}\in V_{\boldsymbol{\lambda}}^*$ (the dual of the lowest weight vector $v_{min}=F^{I_{max}}v_0\in V_{\boldsymbol{\lambda}}$) it follows that one cannot have a power of some $E_i$ in $\Lambda_{(2)}$, hence all positive degree is in $\Lambda_{(1)}$. But then all negative degree also has to be in $\Lambda_{(1)}$, otherwise it does not contributes to the trace. Thus, the only term in $\Delta(\Lambda)$ that contributes to $\kappa(\lambda)$ is $$\frac{1}{|G|}\sum_{g\in G} g\otimes g\cdot F^{I_{max}}\otimes 1\cdot E^{I_{max}}\otimes K^{d(I_{max})}.$$


Noting that $K^{d(I_{max})}=K_{2\rho}^{r'-1}$, we get
\begin{align*}
   \kappa(\lambda)v'_{min}= \text{tr}\,_{V_{\boldsymbol{\lambda}}}(K_{2\rho}^{r'-1}\Lambda_{(1)})\Lambda_{(2)}v'_{min}&=\frac{1}{|G|}\sum_{g\in G}gK^{d(I_{max})}v'_{min}\text{tr}\,_{V_{\boldsymbol{\lambda}}}(K^{d(I_{max})}gF^{I_{max}}E^{I_{max}})\\
    &=\frac{1}{|G|}\sum_{g\in G}gv'_{min}\text{tr}\,_{V_{\boldsymbol{\lambda}}}(gF^{I_{max}}E^{I_{max}})
\end{align*}
Only the vector $v'_{min}$ contributes to the trace inside the previous formula (because $E^{I_{max}}$ is non-zero only on $v_{min}$). Thus, if $F^{I_{max}}E^{I_{max}}v_{min}=\widetilde{\kappa}(\lambda)v_{min}$ then
\begin{align*}
    \kappa(\lambda)v'_{min}=\widetilde{\kappa}(\lambda)v'_{min}
\end{align*}
since the $g$-contributions cancel out for each $g\in G$. Thus $\widetilde{\kappa}(\lambda)=\kappa(\lambda)$. Writing $v_{min}=F^{I_{max}}v_0$, it is easy to see that $\widetilde{\kappa}(\lambda)$ is also the coefficient of $v_0$ in $E^{I_{max}}F^{I_{max}}v_0$ as desired.

Write $\kappa(\lambda)=\kappa_{\Lambda}(\lambda)$. Using that $V_{\boldsymbol{\lambda}}^*\cong V_{-\lambda+(r'-1)\cdot 2\rho}$ and the previous lemma, we get that                                                                               
