Suppose $d(I)=\sum_{i=1}^n a_i\alpha_i$ and $d(J)=\sum_{i=1}^n b_i\alpha_i$. Then
    \begin{itemize}
        \item $E^{I_{max}}(v_I\otimes v'_J)=0$ if $a_i<b_i$ for some $i$.
        \item $F^{I_{max}}(v_I\otimes v'_J)=0$ if $a_i>b_i$ for some $i$.
    \end{itemize}

\label{lemma: commuting F^I with E^I}
For all $f\in U^-, e\in U^+$ one has
    $$[f,e]= \text{ sum of terms with lower } L_R-\text{degree than } e.$$

\label{lemma: change FEmax by cointegral}
    As operators of $X=V_{\boldsymbol{\lambda}}\otimes V_{\boldsymbol{\lambda}}^*$ one has $$F^{I_{max}}E^{I_{max}}|_{X}=\Lambda|_{X} + B$$
    where $B$ is an operator which, when expressed as a matrix in the standard basis of $X$, all coefficients are polynomials in $t^{-1}$ of degree $<(r'-1)(2\rho,\rho)$.

\label{prop: prop surface and coevaluations}
    Let $T_{\Sigma}$ be an $N$-component framed, oriented bottom tangle. Then the Reshetikhin-Turaev operator invariant $\overline{F}(T_{\Sigma},X):\mathbb{C}\to X^{\otimes 2N}$ satisfies
\begin{align}
\label{eq prop: FTX in terms of coev + B}
     \overline{F}(T_{\Sigma},X)=c(q,q^{\lambda})\cdot \overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}^{\otimes 2N}+B
\end{align}
\noindent or graphically
 \begin{figure}[H]
        \centering
        \includegraphics[width=13cm]{FTS,X-is-coevs-graphically.pdf}
    \end{figure}
   \noindent for some coefficient $c(q,q^{\lambda})\in \mathbb{Q}(q,q^{\pm\lambda})$ and where $B:\mathbb{C}\to X^{\otimes 2N}$ has the following property: the coefficients of $B(1)\in X^{\otimes 2N}$ in the standard basis are Laurent polynomials in $t^{-1}$ with $$\text{max-deg}_{t^{-1}}<(r'-1)(\rho,\rho) \cdot N \ \text{ and } \ \text{max-deg}_{t}\leq (r'-1)(\rho,\rho)\cdot N.$$ Moreover, the coefficient $c(q,q^{\lambda})$ is explicitly given by $$c(q,q^{\lambda})=\kappa(\lambda)^N\cdot\overline{\mu}^{\otimes N}(Z_T)$$
        where $\kappa(\lambda)$ is as in Lemma \ref{lemma: CGPT's lemma for cointegral} and $Z_T\in\mathfrak{u}_q^{L}(\mathfrak{g})^{\otimes N}$ is the element defined in Subsection \ref{subs: Seifert formula}.

During the whole proof, by ``coefficients'' we mean coefficients in the standard basis of $X$ or $X^*$ (the dual basis) and tensor products of these. 
\medskip

\textbf{Step 1: Apply algebraic bounds to $Z'_T$.} We begin by applying (\ref{eq: RT of T in terms of universal}) to the LHS of (\ref{eq prop: FTX in terms of coev + B}):
\begin{align*}
     \overline{F}(T_{\Sigma},X)=\mathcal{J}_X\circ F(T_{\Sigma},X), \ \ F(T_{\Sigma},X)=P\circ L_{(Z'_T)^{ev}}\circ  \overrightarrow{\text{coev}}_X^{\otimes N}
\end{align*}
Applying the algebraic bound of Lemma \ref{lemma: algebraic bounds} $N$ times we see that the coefficients of $L_{(Z'_T)^{ev}}\circ  \overrightarrow{\text{coev}}_X^{\otimes N}$, and hence of $F(T_{\Sigma},X)$, are polynomials in $t^{-1}$ with $\text{max-deg}_{t^{-1}}\leq (r'-1)(2\rho,\rho) N$. Note that since there are exactly $N$ repetitions of $\iota_X$ in $\mathcal{J}_X$, the operator $\mathcal{J}_X$ has coefficients in $t^{(r'-1)(\rho,\rho) N}\mathbb{Q}(q)$ (this has the effect of ``symmetrizing'' the powers of $t$ in $F(T_{\Sigma},X)$). This proves that the coefficients of $\overline{F}(T_{\Sigma},X)$ are Laurent polynomials in $t^{\pm 1}$ with $\text{max-deg}_{t^{\pm 1}}\leq (r'-1)(\rho,\rho) N$ (which immediately implies the main result of \cite{LNV:genus-unrolled} by Prop. \ref{prop: Seifert formula}). Our purpose then is to pin down the coefficient of $t^{-(r'-1)(2\rho,\rho) N}$ in $F(T_{\Sigma},X)$. The idea will be to expand $Z'_T$ in the (tensor product) PBW basis of $\mathfrak{u}_q^{L}(\mathfrak{g})^{\otimes N}$ and see which terms contribute (and how) to the power $t^{-(r'-1)(2\rho,\rho) N}$ in $F(T_{\Sigma},X)$.
\medskip

\def\mathfrak{u}_q{\mathfrak{u}_q}

\textbf{Step 2: Expand $Z'_T$ in PBW and discard low $\mathfrak{u}_q^+$-powers.} So let's expand $Z'_T$ in the PBW basis.  One can write $$Z'_T=Z^{top} + Z^{low}$$
where $Z^{low}$ is the sum of all terms in the PBW-expansion of $Z'_T$ having some tensor factor of the form $K^AF^IE^J$ with $J<I_{max}$ and $Z^{top}$ is an element of the form $$Z^{top}=\bigotimes_{i=1}^N h_i(K,F)E^{I_{max}}$$
where $h_i(K,F)$ is a polynomial in $K_j^{\pm 1}$'s and $F_j$'s with $\mathbb{Q}(q)$-coefficients. Note that by Lemma \ref{lemma: algebraic bounds}, $Z^{low}$ does not contribute to the terms of highest degree in $t^{-1}$. More precisely, we have $$F(T_{\Sigma},X)=F(Z'_T,X)=F(Z^{top},X)+F(Z^{low},X)$$
and all coefficients of $F(Z^{low},X)\in X^{\overline{\epsilon}}$ are polynomials in $t^{-1}$  with $\text{max-deg}_{t^{-1}}<(r'-1)(2\rho,\rho)\cdot N$.
\medskip

\textbf{Step 3: Top $\mathfrak{u}_q^+$-power is cointegral.} It is thus enough to prove
\begin{align}
\label{eq proof prop: FTX in terms of coev + B'}
     \overline{F}(Z^{top},X)=(\kappa(\lambda)^N\cdot\overline{\mu}^{\otimes N}(Z_T))\cdot \overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}^{\otimes 2N}+B'
\end{align}
where $B'$ satisfies the same conditions as $B$. For this, we must simply understand the action of $Z^{top}$ on $X^{\otimes N}$. The crucial point is to note that, since $Z'_T$ has degree zero (because the $R$-matrix does) and $F^I=0$ if $d(I)>d(I_{max})$, every term $F^IE^{I_{max}}$ appearing in $Z^{top}$ must satisfy $I=I_{max}$. Hence, $Z^{top}$ has the form $$Z^{top}=\bigotimes_{i=1}^N f_i(K) F^{I_{max}}E^{I_{max}}$$
where each $f_i(K)$ is in the Cartan subalgebra of $\mathfrak{u}_q^{L}(\mathfrak{g})$. Now, by Lemmas \ref{lemma: change FEmax by cointegral} and \ref{lemma: CGPT's lemma for cointegral}, for each $i=1,\dots, N$ we have
\begin{align*}
    f_iF^{I_{max}}E^{I_{max}}|_{X}&=f_i\Lambda|_{X} + B_i\\
    &=\epsilon(f_i)\Lambda|_{X}+B_i\\
    &=\epsilon(f_i)\kappa(\lambda) \cdot\overleftarrow{\text{coev}}_{V_{\boldsymbol{\lambda}}}\circ\overrightarrow{\text{ev}}_{V_{\boldsymbol{\lambda}}}+B_i
\end{align*}
where $B_i$ is an operator with coefficients that are polynomials in $t^{-1}$ satisfying $\text{max-deg}_{t^{-1}}<(r'-1)(2\rho,\rho)$. Note that we used the cointegral property in the second equality. 

\medskip
\textbf{Step 4: The cointegral ``cuts''.} Writing $Z^{top}= Z^{top}_1\otimes\dots\otimes Z^{top}_N$ it follows that
\begin{figure}[H]
    \centering
    \includegraphics[width=14cm]{Proof,_use_cointegral_lemma_N_times.pdf}
\end{figure}


\noindent where $B'_0$ is an operator with coefficients polynomials in $t^{-1}$ with $\text{max-deg}_{t^{-1}}<(r'-1)(2\rho,\rho)\cdot N$ (and $\text{max-deg}_{t}\leq 0$). Letting $c(q,q^{\lambda})=\prod_{i=1}^N\epsilon(f_i)\cdot \kappa(\lambda)^N$ and $$B'=P\circ (\iota_X\otimes \text{id}_X)^{\otimes N}\circ B'_0\circ \overrightarrow{\text{coev}}_X^{\otimes N}$$ we get
\begin{figure}[H]
    \centering
    \includegraphics[width=16cm]{Proof,_FZtop_gets_simplified.pdf}
\end{figure}


Here we used Lemma \ref{lemma: coev lemma} in the third equality while the fourth is obvious ($P_{X,X}$ is just a permutation isomorphism). Since $P$ and $\overrightarrow{\text{coev}}_X^{\otimes N}$ have $\mathbb{Q}$-coefficients and $(\iota_X\otimes \text{id}_X)^{\otimes N}$ has coefficients in $t^{(r'-1)(\rho,\rho) N}\mathbb{Q}(q)$, from what we said about $B'_0$ it follows that $B'$
has coefficients with $\text{max-deg}_{t^{-1}}<(r'-1)(\rho,\rho) N, \text{max-deg}_{t}\leq(r'-1)(\rho,\rho) N$. Summing up, we get
\begin{figure}[H]
    \includegraphics[width=13cm]{Proof,_final_step_summing_up.pdf}
\end{figure}
\begin{comment}







\end{comment}
\noindent and $B:=B'+\overline{F}(Z^{low},X)$ has coefficients with $\text{max-deg}_{t^{-1}}<(r'-1)(\rho,\rho) N, \text{max-deg}_{t}\leq(r'-1)(\rho,\rho) N$ since both $B'$ and $\overline{F}(Z^{low},X)$ have this property. This proves (\ref{eq prop: FTX in terms of coev + B}).

\medskip

\textbf{Step 5: Pinning down $c(q,q^{\lambda})$.} We now prove that $c(q,q^{\lambda})=\kappa(\lambda)^N\overline{\mu}^{\otimes N}(Z_T)$ or equivalently $\prod_{i=1}^N\epsilon(f_i)=\overline{\mu}^{\otimes N}(Z_T)$. To do this, note that $\overline{\mu}(K^AF^IE^J)=0$ unless $I=J=I_{max}$ (where it is =1), so that $$\overline{\mu}^{\otimes N}(Z'_T)=\overline{\mu}^{\otimes N}(Z^{top})=\prod_{i=1}^N\overline{\mu}(f_iF^{I_{max}}E^{I_{max}}).$$
But by definition of $\overline{\mu}$, one has $$\overline{\mu}(f_iF^{I_{max}}E^{I_{max}})=\mu(\Lambda_Gf_iF^{I_{max}}E^{I_{max}})=\mu(f_i\Lambda)=\mu(\epsilon(f_i)\Lambda))=\epsilon(f_i)$$since $\mu(\Lambda)=1$. Finally, note that $\overline{\mu}^{\otimes N}(Z'_T)=\mu^{\otimes N}(Z_T)$ since $\mu(xg)=\mu(gx)$ so that $\overline{\mu}(xg)=\overline{\mu}(x)$ for any group-like $g$ and $x\in \mathfrak{u}_q^{L}(\mathfrak{g})$.
\medskip

Closing up successive strands in the above proposition (and using Prop. \ref{prop: Seifert formula}), we find 

 \begin{figure}[H]
        \centering
        \includegraphics[width=12cm]{Proof_-_Hopf_algebra_integral_and_top_coeff_2.pdf}

    \end{figure}
But since $B$ has coefficients with $\text{max-deg}_{t^{-1}}<(r'-1)(\rho,\rho) N$ then it follows that
\begin{align*}
    \text{least}_{\mathfrak{g},r} \text{ADO}_{\mathfrak{g},r}(\partial\Sigma)&=\text{least}_{\mathfrak{g},r} c(q,q^{\lambda})=(\text{least}_{\mathfrak{g},r} \kappa(\lambda)^N)\overline{\mu}^{\otimes N}(Z_T).
\end{align*}
Since $\text{ADO}_{\mathfrak{g},r}$ and $\kappa(\lambda)$ satisfy the same symmetry property, it follows that \begin{align}
\label{eqtn: proof of Thm 3, with kappa lambda}
    \text{top}_{\mathfrak{g},r} \text{ADO}_{\mathfrak{g},r}(\partial\Sigma)&=\text{top}_{\mathfrak{g},r} c(q,q^{\lambda})=(\text{top}_{\mathfrak{g},r} \kappa(\lambda)^N)\overline{\mu}^{\otimes N}(Z_T).
\end{align}
We can solve for $\text{top}_{\mathfrak{g},r} \kappa(\lambda)$ by plugging in $L=H_-$ (so that $Z_T=v$ and $N=1$ since $H_-$ bounds an annulus with a right-handed twist) and using $\text{top}_{\mathfrak{g},r}(H_-)=q^{-(2\rho,2\rho)}$ as computed in Subsection \ref{subs: Hopf links computation}. This gives $$q^{-(2\rho,2\rho)}=\text{top}_{\mathfrak{g},r}(H_-)=\overline{\mu}(v)\cdot\text{top}_{\mathfrak{g},r}\kappa(\lambda)$$
so that $$\text{top}_{\mathfrak{g},r}\kappa(\lambda)=\frac{q^{-(2\rho,2\rho)}}{\overline{\mu}(v)}.$$
Plugging the latter into (\ref{eqtn: proof of Thm 3, with kappa lambda}) establishes Theorem \ref{theorem: top coefficient formula with integral}.

\label{prop: F(TS,X) as coev but upside-down}
    Let $T_{\Sigma'}$ be a $N'$-component (framed, oriented) top tangle. Then the operator invariant $\overline{F}(T_{\Sigma'},X'):(X')^{\otimes 2N'}\to \mathbb{C}$ satisfies $$\overline{F}(T_{\Sigma'},X')=c'(q,q^{\lambda})\cdot\overleftarrow{\text{ev}}_{V_{\boldsymbol{\lambda}}}^{\otimes 2N'}+B'$$
    or graphically
    \begin{figure}[H]
        \centering
        \includegraphics[width=13cm]{Prop_for_top_tangles.pdf}

    \end{figure}
   \noindent for some $c'(q,q^{\lambda})\in \mathbb{Q}(q,q^{\pm\lambda})$ and where $B'$ evaluates any standard basis vector of $(X')^{\otimes 2N'}$ to a Laurent polynomial in $t$ with $\text{max-deg}_{t}<(r'-1)(\rho,\rho)\cdot N'$ and $\text{max-deg}_{t^{-1}}\leq (r'-1)(\rho,\rho)\cdot N'$.
